WITH with_dims AS (SELECT s.*, p2.rating, p2.supplier_name FROM products s INNER JOIN suppliers p2 ON s.supplier_id = p2.id) SELECT CASE WHEN stock_qty >= 372 THEN 'LARGE' ELSE 'SMALL' END AS stock_qty_tier, COUNT(*) FILTER (WHERE category = 'Books') AS books_rows, MAX(price) FILTER (WHERE brand = 'Initech') AS initech_max_price, ROUND(AVG(price), 2) AS avg_price, COUNT(DISTINCT category) AS distinct_categories, ROUND(AVG(price), 2) AS avg_price_2, COUNT(DISTINCT supplier_id) AS distinct_supplier_ids, GROUPING_ID() AS grouping_id FROM with_dims GROUP BY ROLLUP (CASE WHEN stock_qty >= 372 THEN 'LARGE' ELSE 'SMALL' END) HAVING COUNT(DISTINCT category) < 1
